/// {@template secure_key_response}
/// Represents a secure key pair (public and private keys) generated by
/// [SecureMessaging.generate] or [SecureKey.generateKeyPair].
///
/// This class provides methods for serializing and deserializing the key pair,
/// making it suitable for storage, transmission, and reconstruction.
///
/// The keys are stored as PEM-formatted strings:
/// - **Public key**: Encoded with the appropriate PEM header/footer
///   (e.g., `-----BEGIN RSA PUBLIC KEY-----`)
/// - **Private key**: Encoded with the appropriate PEM header/footer
///   (e.g., `-----BEGIN RSA PRIVATE KEY-----`)
///
/// ### Example usage:
/// ```dart
/// // Create from key generation
/// final response = SecureKeyResponse(
///   publicKey: '-----BEGIN RSA PUBLIC KEY-----\n...\n-----END RSA PUBLIC KEY-----',
///   privateKey: '-----BEGIN RSA PRIVATE KEY-----\n...\n-----END RSA PRIVATE KEY-----',
/// );
///
/// // Serialize to JSON
/// final json = response.toJson();
///
/// // Deserialize from JSON
/// final restored = SecureKeyResponse.fromJson(json);
///
/// // Create empty placeholder
/// final empty = SecureKeyResponse.empty();
/// ```
/// {@endtemplate}
class SecureKeyResponse {
  /// The public key in PEM format.
  ///
  /// This key can be freely shared with other parties. It is used by
  /// [SecureMessaging.encrypt] to encrypt messages that only the
  /// corresponding private key holder can decrypt.
  final String publicKey;

  /// The private key in PEM format.
  ///
  /// This key must be kept secret. It is used by [SecureMessaging.decrypt]
  /// to decrypt messages encrypted with the corresponding public key.
  /// Compromising this key allows an attacker to decrypt all messages
  /// intended for the key owner.
  final String privateKey;

  /// Creates a [SecureKeyResponse] instance.
  ///
  /// - [publicKey]: The public key in PEM format.
  /// - [privateKey]: The private key in PEM format.
  ///
  /// {@macro secure_key_response}
  SecureKeyResponse({
    required this.publicKey,
    required this.privateKey,
  });

  /// Factory constructor to create a [SecureKeyResponse] from a JSON map.
  ///
  /// - [json]: A `Map<String, dynamic>` containing the public and private keys.
  ///
  /// Missing fields default to empty strings. The JSON keys are:
  /// - `"public_key"`: The PEM-encoded public key
  /// - `"private_key"`: The PEM-encoded private key
  ///
  /// Example:
  /// ```dart
  /// final json = {
  ///   "public_key": "-----BEGIN RSA PUBLIC KEY-----...",
  ///   "private_key": "-----BEGIN RSA PRIVATE KEY-----...",
  /// };
  /// final response = SecureKeyResponse.fromJson(json);
  /// ```
  factory SecureKeyResponse.fromJson(Map<String, dynamic> json) {
    return SecureKeyResponse(
      publicKey: json["public_key"] ?? "",
      privateKey: json["private_key"] ?? "",
    );
  }

  /// Factory constructor to create an empty [SecureKeyResponse].
  ///
  /// Both the public and private keys are initialized to empty strings.
  /// Useful as a placeholder or default value when the actual keys are
  /// not yet available.
  factory SecureKeyResponse.empty() => SecureKeyResponse(publicKey: "", privateKey: "");

  /// Converts the [SecureKeyResponse] instance to a JSON map.
  ///
  /// Returns a `Map<String, dynamic>` containing the public and private keys.
  /// The keys are:
  /// - `"public_key"`: The PEM-encoded public key
  /// - `"private_key"`: The PEM-encoded private key
  ///
  /// Example:
  /// ```dart
  /// final response = SecureKeyResponse(
  ///   publicKey: 'pub-key-pem',
  ///   privateKey: 'priv-key-pem',
  /// );
  /// final json = response.toJson();
  /// // {"public_key": "pub-key-pem", "private_key": "priv-key-pem"}
  /// ```
  Map<String, dynamic> toJson() {
    return {
      "public_key": publicKey,
      "private_key": privateKey,
    };
  }
}